/** Floor plate used for each wing (estimated): own key plan, transferred design, or best design candidate only. */
export interface WingFloorPlate {
  wing: number;
  source: 'key-plan' | 'transferred' | 'unlabelled-candidate';
  /** Floor-plan PDF page whose KEY PLAN gives the plate. */
  page: number;
  /** Design id = lowest page drawing the same plate (pages 2|4, 3, 5|8, 6|7). */
  design: number;
  mirrored: boolean;
  /** Key-plan page (x, -y) -> site rotation, deg CCW. */
  rotDeg: number;
  mPerPt: number;
  plateIoU: number;
  notes: string[];
}

