export function flatPlacement(wing: number, flat: number): FlatPlacement | undefined {
  return FLAT_PLACEMENTS.find((p) => p.wing === wing && p.flat === flat);
}

export function flatPlacementsForWing(wing: number): FlatPlacement[] {
  return FLAT_PLACEMENTS.filter((p) => p.wing === wing);
}
